package spms.view;

import spms.components.*;
import spms.controller.ModuleController;
import spms.model.User;
import spms.theme.AppTheme;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.*;

/** Shared app shell. Each of the six modules has its own dedicated workspace. */
public final class MainFrame extends JFrame {
    private final User user;private final ModuleController controller;private final JPanel workspace=new JPanel(new BorderLayout(0,18));private final CardLayout pages=new CardLayout();private final JPanel pageCards=new JPanel(pages);private final Deque<String> history=new ArrayDeque<>();private String current="Dashboard";
    public MainFrame(User user){super("Software Personnel Management System · Workforce Intelligence");this.user=user;controller=new ModuleController(user);setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1360,850);setMinimumSize(new Dimension(1060,680));setLocationRelativeTo(null);setLayout(new BorderLayout());add(sidebar(),BorderLayout.WEST);workspace.setBackground(AppTheme.WORKSPACE);workspace.setBorder(new EmptyBorder(26,30,28,30));add(workspace,BorderLayout.CENTER);showPage("Dashboard",false);}
    private JPanel sidebar(){JPanel side=new JPanel(new BorderLayout());side.setPreferredSize(new Dimension(248,0));side.setBackground(AppTheme.NAVY);JPanel items=new JPanel();items.setOpaque(false);items.setBorder(new EmptyBorder(26,16,16,16));items.setLayout(new BoxLayout(items,BoxLayout.Y_AXIS));JLabel brand=new JLabel("SPMS");brand.setForeground(Color.WHITE);brand.setFont(new Font("Segoe UI Semibold",Font.BOLD,25));items.add(brand);JLabel sub=new JLabel("WORKFORCE INTELLIGENCE");sub.setForeground(new Color(123,151,171));sub.setFont(AppTheme.BODY.deriveFont(Font.BOLD,9));items.add(sub);items.add(Box.createVerticalStrut(30));JLabel section=new JLabel("  WORKSPACE");section.setForeground(new Color(123,151,171));section.setFont(AppTheme.BODY.deriveFont(Font.BOLD,10));items.add(section);items.add(Box.createVerticalStrut(8));
        String[][] nav={{"Dashboard","⌂"},{"User Authentication / Profile","◉"},{"Employee Management","◉"},{"Attendance & Leave","◷"},{"Payroll Management","＄"},{"Performance & Reports","▤"},{"Administration","⚙"}};
        for(String[] item:nav){if(!user.canAccess(item[0]))continue;JButton b=new JButton(item[1]+"    "+item[0]);b.setHorizontalAlignment(SwingConstants.LEFT);b.setForeground(new Color(203,215,225));b.setBackground(AppTheme.NAVY);b.setFont(AppTheme.BODY);b.setBorder(new EmptyBorder(12,12,12,6));b.setFocusPainted(false);b.setMaximumSize(new Dimension(216,44));b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));b.addActionListener(e->showPage(item[0],true));items.add(b);}
        side.add(items,BorderLayout.NORTH);JPanel identity=new JPanel(new BorderLayout(0,8));identity.setOpaque(false);identity.setBorder(new EmptyBorder(12,18,22,18));JLabel who=new JLabel("<html><b>"+escape(user.username())+"</b><br><font color='#9cafc0'>"+escape(user.role().replace('_',' '))+"</font></html>");who.setForeground(Color.WHITE);identity.add(who,BorderLayout.CENTER);SecondaryButton logout=new SecondaryButton("Sign out");logout.addActionListener(e->{dispose();new LoginFrame().setVisible(true);});identity.add(logout,BorderLayout.SOUTH);side.add(identity,BorderLayout.SOUTH);return side;}
    private void showPage(String page,boolean remember){if(remember&&!page.equals(current))history.push(current);current=page;workspace.removeAll();JPanel head=new JPanel(new BorderLayout());head.setOpaque(false);JPanel titles=new JPanel();titles.setOpaque(false);titles.setLayout(new BoxLayout(titles,BoxLayout.Y_AXIS));JLabel crumb=new JLabel("SPMS   /   "+page.toUpperCase(Locale.ROOT));crumb.setForeground(AppTheme.TEAL);crumb.setFont(AppTheme.BODY.deriveFont(Font.BOLD,10));JLabel title=new JLabel(page);title.setForeground(AppTheme.INK);title.setFont(AppTheme.TITLE);JLabel date=new JLabel(LocalDate.now().format(DateTimeFormatter.ofPattern("EEE, d MMM yyyy")));date.setForeground(AppTheme.MUTED);titles.add(crumb);titles.add(Box.createVerticalStrut(4));titles.add(title);titles.add(Box.createVerticalStrut(4));titles.add(new JLabel("Workforce operations at a glance"));head.add(titles,BorderLayout.WEST);
        JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,7,0));actions.setOpaque(false);SecondaryButton back=new SecondaryButton("← Back");back.setEnabled(!history.isEmpty());back.addActionListener(e->goBack());SecondaryButton home=new SecondaryButton("⌂ Dashboard");home.addActionListener(e->showPage("Dashboard",true));actions.add(back);actions.add(home);actions.add(date);head.add(actions,BorderLayout.EAST);workspace.add(head,BorderLayout.NORTH);
        JComponent view=switch(page){case "Dashboard"->new DashboardPanel(controller,user);case "User Authentication / Profile"->profile();case "Employee Management"->new ModuleScreen("employees",controller,user);case "Attendance & Leave"->attendanceScreen();case "Payroll Management"->new ModuleScreen("payroll",controller,user);case "Performance & Reports"->performanceScreen();case "Administration"->adminScreen();default->new ModuleScreen(page,controller,user);};workspace.add(view,BorderLayout.CENTER);workspace.revalidate();workspace.repaint();}
    private void goBack(){if(history.isEmpty())return;current=history.pop();showPage(current,false);}
    private JComponent profile(){JPanel p=new SurfaceCard();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel heading=new JLabel("Signed-in account");heading.setFont(AppTheme.SECTION);p.add(heading);p.add(Box.createVerticalStrut(18));p.add(new JLabel("Username   "+user.username()));p.add(Box.createVerticalStrut(12));p.add(new JLabel("Role   "+user.role().replace('_',' ')));p.add(Box.createVerticalStrut(12));p.add(new JLabel("Employee ID   "+(user.employeeId()==null?"Not linked":user.employeeId())));return p;}
    private JComponent attendanceScreen(){JTabbedPane tabs=new JTabbedPane();tabs.addTab("Attendance",new ModuleScreen("attendance",controller,user));tabs.addTab("Leave requests",new ModuleScreen("leaves",controller,user));return tabs;}
    private JComponent performanceScreen(){JTabbedPane tabs=new JTabbedPane();tabs.addTab("Performance",new ModuleScreen("performance",controller,user));JPanel reports=new JPanel(new BorderLayout(0,12));reports.setBackground(AppTheme.WORKSPACE);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT));buttons.setOpaque(false);for(String[] report:new String[][]{{"employees","Employee report"},{"attendance","Attendance report"},{"leaves","Leave report"},{"payroll","Payroll report"},{"performance","Performance report"}}){SecondaryButton b=new SecondaryButton(report[1]);b.addActionListener(e->{controller.recordReport(report[0],"Opened in Performance & Reports");showPage(report[0],true);});buttons.add(b);}reports.add(buttons,BorderLayout.NORTH);tabs.addTab("Reports",reports);return tabs;}
    private JComponent adminScreen(){JTabbedPane tabs=new JTabbedPane();tabs.addTab("Departments",new ModuleScreen("departments",controller,user));tabs.addTab("User accounts",new ModuleScreen("users",controller,user));JPanel info=new SurfaceCard();info.add(new JLabel("MySQL · SPMS_DB     |     JDBC     |     Passwords protected with salted PBKDF2-HMAC-SHA256"));tabs.addTab("System configuration",info);return tabs;}
    private static String escape(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
}
